#include <bits/stdc++.h>
using namespace std;

struct CustomHash {
    static uint64_t splitmix64(uint64_t x) {
        x += 0x9e3779b97f4a7c15ULL;
        x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ULL;
        x = (x ^ (x >> 27)) * 0x94d049bb133111ebULL;
        return x ^ (x >> 31);
    }

    size_t operator()(long long x) const {
        static const uint64_t FIXED_RANDOM =
            chrono::steady_clock::now().time_since_epoch().count();
        return splitmix64((uint64_t)x + FIXED_RANDOM);
    }
};

using HashMap = unordered_map<long long, vector<int>, CustomHash>;

int N, Q;
long long K;
vector<long long> A;
HashMap mpU, mpV;

int countKey(const HashMap &mp, long long key, int l, int r) {
    if (l > r) return 0;

    auto it = mp.find(key);
    if (it == mp.end()) return 0;

    const vector<int> &v = it->second;
    if (v.empty() || v.front() > r || v.back() < l) return 0;

    auto itL = lower_bound(v.begin(), v.end(), l);
    auto itR = upper_bound(v.begin(), v.end(), r);
    return int(itR - itL);
}

long long leftQuery(long long p, long long a, int L, int R) {
    if (L > R) return 0;

    long long rrLL = min<long long>(R, p - 1);
    if (L > rrLL) return 0;

    int rr = (int)rrLL;
    long long ans = 0;

    long long start1LL = max<long long>(L, p - K);
    if (start1LL <= rr) {
        ans += countKey(mpU, a + p - K, (int)start1LL, rr);
    }

    long long start2LL = max<long long>(L, p - K + 1);
    if (start2LL <= rr) {
        ans += countKey(mpV, K - p + a, (int)start2LL, rr);
    }

    return ans;
}

long long rightQuery(long long p, long long a, int L, int R) {
    if (L > R) return 0;

    long long llLL = max<long long>(L, p + 1);
    if (llLL > R) return 0;

    int ll = (int)llLL;
    long long ans = 0;

    long long end1LL = min<long long>(R, p + K);
    if (ll <= end1LL) {
        ans += countKey(mpU, a + p + K, ll, (int)end1LL);
    }

    long long end2LL = min<long long>(R, p + K - 1);
    if (ll <= end2LL) {
        ans += countKey(mpV, a - p - K, ll, (int)end2LL);
    }

    return ans;
}

struct DSU {
    vector<int> parent, sz, mn, mx;
    vector<char> active;

    DSU(int n = 0) {
        if (n) init(n);
    }

    void init(int n) {
        parent.resize(n + 1);
        sz.assign(n + 1, 1);
        mn.resize(n + 1);
        mx.resize(n + 1);
        active.assign(n + 1, 0);

        for (int i = 1; i <= n; ++i) {
            parent[i] = i;
            mn[i] = mx[i] = i;
        }
    }

    int find(int v) {
        if (parent[v] != v) parent[v] = find(parent[v]);
        return parent[v];
    }

    void unite(int a, int b) {
        a = find(a);
        b = find(b);

        if (a == b) return;

        if (sz[a] < sz[b]) swap(a, b);

        parent[b] = a;
        sz[a] += sz[b];
        mn[a] = min(mn[a], mn[b]);
        mx[a] = max(mx[a], mx[b]);
    }

    void activate(int x) {
        active[x] = 1;
        parent[x] = x;
        sz[x] = 1;
        mn[x] = mx[x] = x;

        if (x > 1 && active[x - 1]) unite(x, x - 1);
        if (x + 1 < (int)active.size() && active[x + 1]) unite(x, x + 1);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N >> Q >> K;

    A.assign(N + 1, 0);
    for (int i = 1; i <= N; ++i) {
        cin >> A[i];
    }

    mpU.reserve((N + 5) * 2);
    mpV.reserve((N + 5) * 2);
    mpU.max_load_factor(0.7);
    mpV.max_load_factor(0.7);

    for (int i = 1; i <= N; ++i) {
        long long u = A[i] + i;
        long long v = A[i] - i;

        mpU[u].push_back(i);
        mpV[v].push_back(i);
    }

    long long initial = 0;

    for (int j = 1; j <= N; ++j) {
        initial += leftQuery(j, A[j], 1, j - 1);
    }

    vector<int> del(N + 1, 0), D(Q + 1);

    for (int t = 1; t <= Q; ++t) {
        cin >> D[t];
        del[D[t]] = t;
    }

    DSU dsu(N);

    for (int i = 1; i <= N; ++i) {
        if (del[i] == 0) {
            dsu.activate(i);
        }
    }

    vector<long long> add(Q + 1, 0);

    for (int t = Q; t >= 1; --t) {
        int x = D[t];

        int L1 = 1, R1 = 0;
        int L2 = N + 1, R2 = 0;

        if (x > 1 && dsu.active[x - 1]) {
            int root = dsu.find(x - 1);
            L1 = dsu.mn[root];
            R1 = dsu.mx[root];
        }

        if (x < N && dsu.active[x + 1]) {
            int root = dsu.find(x + 1);
            L2 = dsu.mn[root];
            R2 = dsu.mx[root];
        }

        long long curAdd = 0;

        if (L1 <= R1) {
            curAdd += leftQuery(x, A[x], L1, R1);
        }

        if (L2 <= R2) {
            curAdd += rightQuery(x, A[x], L2, R2);
        }

        if (L1 <= R1 && L2 <= R2) {
            int sizeL = R1 - L1 + 1;
            int sizeR = R2 - L2 + 1;

            if (sizeL <= sizeR) {
                for (int p = L1; p <= R1; ++p) {
                    curAdd += rightQuery(p, A[p], L2, R2);
                }
            } else {
                for (int p = L2; p <= R2; ++p) {
                    curAdd += leftQuery(p, A[p], L1, R1);
                }
            }
        }

        add[t] = curAdd;

        dsu.activate(x);
    }

    vector<long long> ans(Q + 1);
    long long cur = initial;
    ans[0] = cur;

    for (int t = 1; t <= Q; ++t) {
        cur -= add[t];
        ans[t] = cur;
    }

    for (int t = 0; t <= Q; ++t) {
        cout << ans[t] << '\n';
    }

    return 0;
}
